package com.adib.maintenance;
import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class FocusedViewsTest {
 JSONObject previous;
 @Before public void before()throws Exception{previous=AccountSession.user;AccountSession.user=new JSONObject().put("id","test").put("name","Ilqar").put("role","admin");}
 @After public void after(){AccountSession.user=previous;}
 void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(MainActivity a,String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(a);}void call(MainActivity a,String n)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 @Test public void discussionsAreActivityContentAndBackFirstReturnsToList()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"chatRequestRunning",true);set(a,"lastChatRefreshAt",android.os.SystemClock.elapsedRealtime()+10000);call(a,"showChat");assertNotNull(a.findViewById(android.R.id.content).findViewWithTag("discussions-screen"));assertEquals(Boolean.TRUE,get(a,"chatScreenOpen"));assertNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());set(a,"chatConversationOpen",true);a.onBackPressed();assertEquals(Boolean.FALSE,get(a,"chatConversationOpen"));assertEquals(Boolean.TRUE,get(a,"chatScreenOpen"));}
 @Test public void taskHeaderIsOneRow()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"screen","home");call(a,"render");LinearLayout toolbar=(LinearLayout)((View)get(a,"root")).findViewWithTag("compact-view-toolbar");int visible=0;for(int i=0;i<toolbar.getChildCount();i++)if(toolbar.getChildAt(i).getVisibility()==View.VISIBLE)visible++;assertEquals(1,visible);}
 @Test public void matrixHeaderDoesNotIncludeSecondActionRow()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"screen","list");set(a,"mode","matrix");call(a,"render");LinearLayout toolbar=(LinearLayout)((View)get(a,"root")).findViewWithTag("compact-view-toolbar");assertEquals(1,toolbar.getChildCount());}
 @Test public void calendarFilterIsInsideDateNavigation(){TaskCalendarActivity a=Robolectric.buildActivity(TaskCalendarActivity.class).get();a.message="Saxlanan tapşırıqlar";a.phone=new CalendarPhoneUi(a);a.phone.render();View filter=a.root.findViewWithTag("calendar-filter-button");assertNotNull(filter);assertNotSame(a.root,filter.getParent());assertEquals(View.GONE,a.status.getVisibility());assertNotNull(a.root.findViewWithTag("compact-calendar-toolbar"));}
}
